+  includeCauses: IncludeCauses;
+  maxCauseDepth: number;
+  sanitizeMessage: boolean;
+  classFilter: string[];
+}
+
+export function normalizeErrorStackOptions(
+  input: unknown
+): NormalizedErrorStackOptions | undefined {
+  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
+    return undefined;
+  }
+
+  const value = input as Record<string, unknown>;
+  let mode: ErrorStackMode =
+    value.mode === 'string' || value.mode === 'frames' || value.mode === 'off'
+      ? value.mode
+      : 'off';
+  const maxStackLines = value.maxStackLines;
+  if (
+    maxStackLines !== undefined &&
+    (!Number.isInteger(maxStackLines) || (maxStackLines as number) <= 0)
+  ) {
+    mode = 'off';
+  }
+
+  let includeCauses: IncludeCauses =
+    value.includeCauses === 'direct' || value.includeCauses === 'deep'
+      ? value.includeCauses
+      : 'none';
+  const configuredDepth = value.maxCauseDepth;
+  if (configuredDepth !== undefined && !Number.isInteger(configuredDepth)) {
+    includeCauses = 'none';
+  }
+
+  const classFilter = Array.isArray(value.classFilter)
+    ? value.classFilter.filter((name): name is string => typeof name === 'string')
+    : typeof value.classFilter === 'string' && value.classFilter
+      ? [value.classFilter]
+      : [];
+
+  return {
+    mode,
+    normalizeNewlines: value.normalizeNewlines === true,
+    trimLeadingWhitespace: value.trimLeadingWhitespace !== false,
+    maxStackLines: Number.isInteger(maxStackLines)
+      ? (maxStackLines as number)
+      : undefined,
+    stripInternalFrames:
+      value.stripInternalFrames === 'node' ||
