+import { NormalizedErrorStackOptions } from './error-options.js';
+
+type StackOptions = Pick<
+  NormalizedErrorStackOptions,
+  | 'normalizeNewlines'
+  | 'trimLeadingWhitespace'
+  | 'maxStackLines'
+  | 'stripInternalFrames'
+  | 'redactPaths'
+>;
+
+export function normalizeStackNewlines(stack: string): string {
+  return stack.replace(/\\r\
?/g, '\
');
+}
+
+function stripInternal(lines: string[], mode: StackOptions['stripInternalFrames']) {
+  return lines.filter((line, index) => {
+    if (index === 0) return true;
+    const node = line.includes('node:internal');
+    const superjson =
+      line.includes('src/transformer.ts') ||
+      line.includes('src/plainer.ts') ||
+      line.includes('src/index.ts');
+    return !(
+      (mode === 'node' && node) ||
+      (mode === 'superjson' && superjson) ||
+      (mode === 'node_and_superjson' && (node || superjson))
+    );
+  });
+}
+
+function redactLine(line: string, mode: StackOptions['redactPaths']): string {
+  if (mode === 'strip_cwd') {
+    const cwd = process.cwd().replace(/\\\\/g, '/');
+    return line.replace(new RegExp(cwd.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'), 'g'), '');
+  }
+  if (mode === 'basename') {
+    return line.replace(/(?:[A-Za-z]:)?(?:[\\\\/][^\\\\/()\\s]+)+/g, path => {
+      const segments = path.split(/[\\\\/]/);
+      return segments[segments.length - 1];
+    });
+  }
+  return line;
+}
+
+function initialLines(stack: string, options: StackOptions): string[] {
+  const value = options.normalizeNewlines ? normalizeStackNewlines(stack) : stack;
+  return value.split('\
').map((line, index) =>
+    index > 0 && options.trimLeadingWhitespace ? line.replace(/^\\s+/, '') : line
+  );
+}
+
+export function processStackString(stack: string, options: StackOptions): string {
+  let lines = initialLines(stack, options);
+  lines = lines.map(line => redactLine(line, options.redactPaths));
+  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
+  lines = stripInternal(lines, options.stripInternalFrames);
+  return lines.join('\
');
+}
+
+export function processStackFrames(
+  stack: string,
+  options: StackOptions
+): Array<{ raw: string }> {
+  let lines = initialLines(stack, options);
+  lines = stripInternal(lines, options.stripInternalFrames);
+  lines = lines.map(line => redactLine(line, options.redactPaths));
+  if (options.maxStackLines !== undefined) lines = lines.slice(0, options.maxStackLines);
+  return lines.map(raw => ({ raw }));
+}
