+function matchesClassFilter(error: Error, superJson: SuperJSON): boolean {
+  const filter = superJson.errorStack?.classFilter;
+  return !filter || filter.length === 0 || filter.includes(error.name);
+}
+
+function shouldProcessStack(
+  error: Error,
+  superJson: SuperJSON,
+  mode: 'string' | 'frames'
+): boolean {
+  return (
+    superJson.errorStack?.mode === mode && matchesClassFilter(error, superJson)
+  );
+}
+
+function serializeError(error: Error, superJson: SuperJSON): Record<string, any> {
+  if (!superJson.errorStack) {
+    const baseError: Record<string, any> = {
+      name: error.name,
+      message: error.message,
+    };
+    if ('cause' in error) baseError.cause = (error as any).cause;
+    superJson.allowedErrorProps.forEach(prop => {
+      baseError[prop] = (error as any)[prop];
+    });
+    return baseError;
+  }
+
+  return serializeConfiguredError(error, superJson);
+}
+
+function serializeConfiguredError(
+  error: Error,
+  superJson: SuperJSON
+): Record<string, any> {
+  return serializeConfiguredErrorAtDepth(error, superJson, 0, new Set<Error>());
+}
+
+function serializeConfiguredErrorAtDepth(
+  error: Error,
+  superJson: SuperJSON,
+  depth: number,
+  seen: Set<Error>
+): Record<string, any> {
+  const options = superJson.errorStack;
+  // This is only called for configured instances, but retaining this guard keeps
+  // the function safe for future transformer reuse.
+  if (!options) return serializeError(error, superJson);
+
+  const matches = matchesClassFilter(error, superJson);
+  const plain: Record<string, any> = {
+    name: error.name,
+    message:
+      matches && options.sanitizeMessage
+        ? sanitizeMessage(error.message)
+        : error.message,
+  };
+
+  superJson.allowedErrorProps.forEach(prop => {
+    if (prop !== 'stack' && prop !== 'stackFrames') {
+      plain[prop] = (error as any)[prop];
+    }
+  });
+
+  if (matches && options.mode === 'string' && superJson.allowedErrorProps.includes('stack')) {
+    if (typeof error.stack === 'string') {
+      plain.stack = processStackString(error.stack, options);
+    }
+  }
+  if (matches && options.mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) {
+    if (typeof error.stack === 'string') {
+      plain.stackFrames = processStackFrames(error.stack, options);
+    }
+  }
+
+  if (error instanceof (globalThis as any).AggregateError) {
+    plain.errors = (error as any).errors;
+  }
+
+  const cause = (error as any).cause;
+  const canIncludeCause =
+    options.includeCauses === 'direct'
+      ? depth === 0
+      : options.includeCauses === 'deep' && depth < options.maxCauseDepth;
